class widget {
    struct impl;
    static constexpr std::size_t kSize = 64;
    alignas(std::max_align_t) std::byte storage_[kSize];    // the body lives here
    impl* get() noexcept { return std::launder(reinterpret_cast<impl*>(&storage_)); }
public:
    widget();
    ~widget();                                              // .cpp: std::destroy_at(get())
    void draw();
};
// widget.cpp
static_assert(sizeof(widget::impl) <= widget::kSize, "increase kSize");

class widget {
    struct impl; impl* pimpl_;                       // raw: ownership is manual
public:
    widget(const widget&);
    widget& operator=(const widget&);
    ~widget();                                       // all three in the .cpp
};
widget::widget(const widget& o) : pimpl_(new impl(*o.pimpl_)) {}
widget::~widget() { delete pimpl_; }
